//! 🧪️ Actual original edit fields produce independent decoded causal messages and return every lease.
use super::*;
use semio_framework_value::{FromValue,retained_clone::RetainedCloneSource};
fn fund(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
fn fixture_edit(f:&serde_json::Value)->Edit<String>{
        let metadata=(0..2).map(|i|serde_json::json!({"mutation_id":format!("edit#{i}"),"dependencies":if i==0{vec!["prior"]}else{vec!["edit#0"]},"base_version":0,"author_id":f["actor"],"timestamp":{"actor":7,"physical_ms":9,"logical":i},"undo_policy":"SemanticUndo","transaction":{"id":"run/8","tool":"energy.simulate"}})).collect::<Vec<_>>();
        Edit::<String>::from_value(serde_json::json!({"id":"edit","actor":f["actor"],"line":"main","forwards":f["forwards"],"inverse":f["inverse"],"mutationMeta":metadata,"verb":"energy.edit","sequenceNumber":0,"startedAt":"now"}).into()).unwrap()

}
#[test]
fn original_edit_pages_match_causal_protocol_and_close_cancelled_prefixes(){
    let f:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
    for cut in std::iter::once(None).chain(f["cancelAt"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){
        let edit=fixture_edit(&f);
        let pointer=edit.forwards.as_ptr();let d=RetainedCloneSource::<Edit<String>>::owned_constructor_demand::<()>();let(mut source,_)=RetainedCloneSource::admit_owned(edit,(),RetainedCloneGrant{maximum_copy_bytes:RetainedCloneSource::<Edit<String>>::constructor_copy_bytes(),..fund(RetirementDemand{capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})}).map_err(|(error,..)|error).unwrap();
        let mut original=Some(source.retain_original(fund(RetainedOwnedProjection::<Edit<String>>::constructor_demand())).unwrap().0);
        let wire=ArtifactOperationWire::canonical().with_original_target(semio_framework_os_store_one_item_publication::lifted_prepared_operation_wire::whole_document_target::<String>);
        let d=ArtifactOriginalEditWire::<String>::birth_demands();assert!(d.copy_bytes<=4096);let(mut owner,_)=ArtifactOriginalEditWire::admit(&mut original,wire,1<<20,4<<20,fund(d)).unwrap().unwrap();
        let headers=OriginalEditWireHeaders{document:f["document"].as_str().unwrap(),schema:f["schema"].as_str().unwrap(),observed:f["observed"].as_str()};
        for turn in 0..100000{if cut.is_some_and(|cut|turn>=cut)||owner.payload_ready(){break}let d=owner.demands(4096).unwrap();assert!(d.copy_bytes<=4096,"phase {} demand {}",owner.phase,d.copy_bytes);for axis in 0..5{let mut g=fund(d);let limit=match axis{0=>&mut g.maximum_items,1=>&mut g.maximum_copy_bytes,2=>&mut g.maximum_capacity_bytes,3=>&mut g.maximum_release_bytes,_=>&mut g.maximum_depth};if *limit==0{continue}*limit-=1;let frontier=(owner.phase,owner.row,owner.length,owner.offset,owner.output.len());let(step,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(headers,g).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert_eq!((owner.phase,owner.row,owner.length,owner.offset,owner.output.len()),frontier);}let(step,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(headers,fund(d)).unwrap());let p=step.progress();assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(p.fits(fund(d)));assert!(turn<99999,"phase {} stalled",owner.phase);}
        if cut.is_none(){let bytes:Vec<u8>=owner.output.iter().collect();let rows=semio_framework_replication_causal::binary::decode_envelopes(&bytes).unwrap();assert_eq!(rows.len(),2);for(i,row)in rows.iter().enumerate(){assert_eq!(row.document_id.0,headers.document);assert_eq!(row.mutation_id.0,format!("edit#{i}"));assert_eq!(row.observed.as_ref().unwrap().0,headers.observed.unwrap());assert_eq!(row.actor.0.as_str(),f["actor"].as_str().unwrap());assert_eq!(row.diff.payload.to_vec_owner(),[b"op".as_slice(),serde_json::to_vec(f["forwards"][i].as_str().unwrap()).unwrap().as_slice()].concat());assert_eq!(row.inverse.payload.to_vec_owner(),[b"op".as_slice(),serde_json::to_vec(f["inverse"][i].as_str().unwrap()).unwrap().as_slice()].concat());assert_eq!(row.transaction.as_ref().unwrap().id,"run/8");}assert_eq!(semio_framework_replication_causal::binary::encode_envelopes(&rows),bytes);}
        owner.begin_close();for turn in 0..100000{if owner.terminal_is_empty(){break}let d=owner.close_demands(4096).unwrap();let(step,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(fund(d)).unwrap());let p=step.progress();assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(turn<99999);}
        assert_eq!(source.borrow().get().forwards.as_ptr(),pointer);while !source.terminal_is_empty(){let d=source.next_close_demand(4096).unwrap();source.close_step(fund(d)).unwrap();}
    }
}

#[test]
fn original_edit_message_returns_same_box_and_physically_closes_all_custody_prefixes(){
    let f:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
    for cut in std::iter::once(None).chain(f["cancelAt"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){
        let mut original=Some(Box::new(fixture_edit(&f)));let pointer=&**original.as_ref().unwrap()as *const Edit<String>;let rows=original.as_ref().unwrap().forwards.as_ptr();
        let wire=ArtifactOperationWire::canonical().with_original_target(semio_framework_os_store_one_item_publication::lifted_prepared_operation_wire::whole_document_target::<String>);
        let d=ArtifactOriginalEditMessage::<String>::birth_demands();assert!(d.copy_bytes<=4096);let((mut owner,p),h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||ArtifactOriginalEditMessage::admit(&mut original,wire,fund(d)).unwrap().unwrap());assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(original.is_none());
        let headers=OriginalEditWireHeaders{document:f["document"].as_str().unwrap(),schema:f["schema"].as_str().unwrap(),observed:f["observed"].as_str()};
        for turn in 0..100000{if cut.is_some_and(|cut|turn>=cut)||owner.ready(){break}let d=owner.demands(4096).unwrap();assert!(d.copy_bytes<=4096);let(step,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(headers,fund(d)).unwrap());let p=step.progress();assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(turn<99999);}
        if cut.is_none(){let d=owner.demands(4096).unwrap();let((edit,bytes,p),h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.take(fund(d)).unwrap().unwrap());assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert_eq!(&*edit as *const Edit<String>,pointer);assert_eq!(edit.forwards.as_ptr(),rows);assert_eq!(semio_framework_replication_causal::binary::decode_envelopes(&bytes.to_vec_owner()).unwrap().len(),2);drop((edit,bytes));}
        owner.begin_close();for turn in 0..100000{if owner.terminal_is_empty(){break}let d=owner.close_demands(4096).unwrap();let(step,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(fund(d)).unwrap());let p=step.progress();assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(turn<99999);}
    }
}
fn now()->Option<u64>{Some(1)}
fn stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1<<28,maximum_copy_bytes:1<<28,maximum_capacity_bytes:1<<26,maximum_release_bytes:1<<26,maximum_depth:4096}}
#[test]
fn original_caller_admits_edit_message_and_real_cancel_only_allows_original_retirement(){
    use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation,OriginalConstructionDemand,admit_original_construction,close_original_retained_step};
    let mut f:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let repeat=f["callerRepeat"].as_u64().unwrap()as usize;for field in ["forwards","inverse"]{for value in f[field].as_array_mut().unwrap(){*value=serde_json::Value::String(value.as_str().unwrap().repeat(repeat));}}
    for cut in std::iter::once(None).chain(f["cancelAt"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){
        let mut caller=OriginalJobFixtureCaller::admit(OperationId(814),Generation(8),stock(),now,1000,1<<26);let mut decoder=OriginalJobDecodeOwner::empty();let mut edit=Some(Box::new(fixture_edit(&f)));let mut owner=None;
        let wire=with_original_edit_message(ArtifactOperationWire::canonical().with_original_target(semio_framework_os_store_one_item_publication::lifted_prepared_operation_wire::whole_document_target::<String>));
        let d=(wire.original_message_birth.unwrap())();let(result,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(fund(d),&mut decoder,|cx|admit_original_construction(cx,&mut owner,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|Ok((wire.original_message_admission.unwrap())(&mut edit,wire,fund(d))?.unwrap()))));assert!(result.unwrap());assert_eq!((h.requested_bytes,h.released_bytes),(caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes));let owner=owner.as_mut().unwrap();
        let headers=OriginalEditWireHeaders{document:f["document"].as_str().unwrap(),schema:f["schema"].as_str().unwrap(),observed:f["observed"].as_str()};
        for turn in 0..100000{if cut.is_some_and(|cut|turn>=cut)||owner.ready(){break}let d=owner.next_message_demand(4096).unwrap();assert!(d.copy_bytes<=4096&&d.capacity_bytes<=4096,"original paged message quantum {d:?}");let(result,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(fund(d),&mut decoder,|cx|{let mut posted=None;admit_original_construction(cx,&mut posted,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|Ok(((),owner.advance_message(headers.document,headers.schema,headers.observed,fund(d))?.progress())))}));assert!(result.unwrap());assert_eq!((h.requested_bytes,h.released_bytes),(caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes));assert!(turn<99999);}
        if cut.is_none(){assert!(owner.ready())}else{caller.cancel().cancel_now();let d=owner.next_message_demand(4096).unwrap();assert!(!caller.turn_with_decoder(fund(d),&mut decoder,|cx|{let mut posted=None;admit_original_construction(cx,&mut posted,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|Ok(((),owner.advance_message(headers.document,headers.schema,headers.observed,fund(d))?.progress())))}).unwrap());assert_eq!(caller.receipt(),Default::default());}
        owner.begin_close();for turn in 0..100000{if owner.terminal_is_empty(){break}let d=owner.next_demand(4096).unwrap();let(result,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(fund(d),&mut decoder,|cx|cx.with_original_retirement(|cx|close_original_retained_step(cx,d,|g|{let step=owner.close_step(g)?;semio_framework_value::retained_clone::admit_retained_clone_close(g,step,owner.terminal_is_empty(),"original edit message port")}))));result.unwrap();assert_eq!((h.requested_bytes,h.released_bytes),(caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes));assert!(turn<99999);}
        while !decoder.terminal_is_empty(){let d=decoder.retirement_demands(4096).unwrap();let(result,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(fund(d),|cx|cx.with_original_retirement(|cx|close_original_retained_step(cx,d,|g|decoder.close_step(g)))));result.unwrap();assert_eq!((h.requested_bytes,h.released_bytes),(caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes));}caller.retire(stock());
    }
}
